INSERT INTO public.products
  (name,name_ar,slug,price,original_price,discount,description,description_ar,images,
   category,category_id,brand,brand_id,has_sizes,sizes,color_variants,features,specs,
   in_stock,stock_quantity,is_active,countries,is_featured,is_best_seller,audience,sort_order)
SELECT
  d.payload->>'name',d.payload->>'name_ar',d.payload->>'slug',
  (d.payload->>'price')::numeric,(d.payload->>'original_price')::numeric,
  (d.payload->>'discount')::integer,d.payload->>'description',d.payload->>'description_ar',
  ARRAY(SELECT jsonb_array_elements_text(d.payload->'images')),
  c.slug,c.id,NULL,NULL,(d.payload->>'has_sizes')::boolean,
  ARRAY(SELECT jsonb_array_elements_text(d.payload->'sizes')),
  d.payload->'color_variants',d.payload->'features',d.payload->'specs',
  false,0,false,ARRAY['YE','SA']::text[],
  (d.payload->>'is_featured')::boolean,(d.payload->>'is_best_seller')::boolean,
  d.payload->>'audience',(d.payload->>'sort_order')::integer
FROM _genan_demo_seed d
JOIN public.categories c ON c.slug=(d.payload->>'category')
ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.inventory_skus
  (product_id,variant_key,label,color_name,color_hex,color_hex2,size,stock_quantity,is_default)
SELECT p.id,s->>'variant_key',s->>'label',s->>'color_name',s->>'color_hex',NULL,
       nullif(s->>'size',''),0,(s->>'is_default')::boolean
FROM _genan_demo_seed d
JOIN public.products p ON p.slug=d.payload->>'slug'
CROSS JOIN LATERAL jsonb_array_elements(d.payload->'skus') s
ON CONFLICT (product_id,variant_key) DO NOTHING;
COMMIT;